/*
 * Q62: Ignore SIGINT, then restore its default action using sigaction().
 */
#include <stdio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

int main(void)
{
    struct sigaction action = {0};
    sigemptyset(&action.sa_mask);
    // Temporarily ignore SIGINT, which is normally generated by Ctrl+C.
    action.sa_handler = SIG_IGN;
    if (sigaction(SIGINT, &action, NULL) == -1)
    {
        perror("sigaction ignore");
        return 1;
    }
    printf("PID: %ld. SIGINT ignored for 5 seconds; try Ctrl+C now.\n", (long)getpid());
    fflush(stdout);
    // Keep this phase active for five seconds so there is time to try Ctrl+C.
    struct timespec remaining = {.tv_sec = 5, .tv_nsec = 0};
    // If another signal interrupts the sleep, continue sleeping for the time left.
    while (nanosleep(&remaining, &remaining) == -1)
    {
        if (errno != EINTR)
        {
            perror("nanosleep");
            return 1;
        }
    }
    // Restore the normal SIGINT action, which terminates the process.
    action.sa_handler = SIG_DFL;
    if (sigaction(SIGINT, &action, NULL) == -1)
    {
        perror("sigaction default");
        return 1;
    }
    puts("SIGINT default restored. Ctrl+C (or kill -INT PID) now terminates me.");
    fflush(stdout);
    /* Ignored signals are discarded; a NEW SIGINT is needed after reset. */
    // Wait for a new SIGINT so the restored default action can be observed.
    for (;;)
    {
        pause();
    }
}
